challenges.solution:
limit = int(input())
n = int(input())
streak = 0
locked_at = 0

for attempt in range(1, n + 1):
    result = input()
    if locked_at > 0:
        continue
    if result == "FAIL":
        streak = streak + 1
        if streak == limit:
            locked_at = attempt
    else:
        streak = 0

if locked_at > 0:
    print("LOCKED at attempt", locked_at)
else:
    print("NOT LOCKED")
